window.OSHA_QUESTIONS_SET4 = [
  { id: "dm-01", category: "demolition", topic: "Subparte T", q: "La demolición de construcción está cubierta por:", choices: ["1926 Subparte T", "solo 1910.146", "solo 1926 Subparte M", "exclusivamente la cláusula de deber general"], a: 0, why: "1926.850–860: estudio de ingeniería, servicios y demolición secuencial." },
  { id: "dm-02", category: "demolition", topic: "Estudio de ingeniería", q: "Antes de la demolición, una persona competente debe hacer un escrito:", choices: ["Estudio de ingeniería de la condición de la estructura y la posibilidad de colapso no planificado", "Folleto de mercadeo", "Solo una foto", "Adivinanza verbal"], a: 0, why: "1926.850(a): estudio escrito. Revise también las estructuras adyacentes." },
  { id: "dm-03", category: "demolition", topic: "Servicios en demolición", q: "Las líneas de electricidad, gas, agua, vapor y otros servicios deben:", choices: ["Cortarse, taparse o controlarse de otro modo fuera del edificio antes de la demolición, salvo lo necesario y protegido", "Dejarse vivas para la iluminación", "Cortarse al azar", "Ignorarse si el edificio está vacío"], a: 0, why: "1926.850(c): localice y proteja las líneas que queden. Llame al 811 para servicios enterrados." },
  { id: "dm-04", category: "demolition", topic: "Materiales peligrosos", q: "Antes de la demolición, el empleador debe determinar si:", choices: ["Hay asbesto, plomo, PCB u otros materiales peligrosos y manejarlos bajo las normas aplicables", "El edificio es solo histórico", "El color de la pintura coincide", "Solo hay ratas"], a: 0, why: "Asbesto NESHAP, plomo 1926.62 y 1910.120 si se convierte en un sitio de desechos. Primero el estudio." },
  { id: "dm-05", category: "demolition", topic: "Tolvas", q: "Las tolvas de escombros en general necesitan:", choices: ["Aberturas cerradas o resguardadas; una compuerta sustancial en cada abertura de la tolva cuando no está atendida", "Tolvas abiertas en cada piso sin protección", "Trabajadores parados bajo la descarga", "Solo forro de cartón"], a: 0, why: "1926.852: tolvas. Mantenga a las personas fuera de la zona de caída." },
  { id: "dm-06", category: "demolition", topic: "Aberturas de piso en demolición", q: "Los huecos cortados para dejar caer escombros deben:", choices: ["Barricadarse y no usarse como pasarelas; cubiertas cuando se exijan", "Dejarse sin marcar como atajo", "Cubrir solo con visqueen", "Usarse como sustituto de escaleras"], a: 0, why: "1926.850(k) y Subparte M: peligros de caída y de objetos que caen." },
  { id: "dm-07", category: "demolition", topic: "Muros", q: "Los muros no se dejarán en pie salvo que:", choices: ["Estén estables contra el viento y otras fuerzas, o estén apuntalados", "Se vean derechos", "El inspector no haya llegado", "Tengan papel tapiz"], a: 0, why: "1926.854–855: muros de mampostería, arcos de piso. Demolición secuencial para no crear un colapso." },
  { id: "dm-08", category: "demolition", topic: "Escaleras en demolición", q: "Durante la demolición, las escaleras, pasajes y escaleras de mano asignados deben:", choices: ["Mantenerse e iluminarse de forma adecuada; el demás acceso cerrado", "Quitarse primero siempre", "Usarse para almacenar escombros", "Quedar sin luz para ahorrar energía"], a: 0, why: "1926.850(m)–(n): mantenga un camino seguro para los trabajadores que siguen en el edificio." },
  { id: "dm-09", category: "demolition", topic: "Demolición mecánica", q: "Al usar una bola de demolición o una excavadora de largo alcance:", choices: ["Mantenga a los trabajadores fuera del área de peligro; el operador debe tener vista clara o una persona de señales", "Párese junto al muro que se está jalando", "Use una línea de guía en la bola con gente debajo", "Trabaje de noche sin luces"], a: 0, why: "1926.859: demolición mecánica. Los colapsos inesperados viajan más lejos de lo que piensa." },
  { id: "dm-10", category: "demolition", topic: "Demolición de acero", q: "Las estructuras de acero que se desmontan:", choices: ["Necesitan un plan para que no se dejen caer miembros; el piso debe permanecer en su lugar salvo las aberturas necesarias", "Pueden cortarse con soplete para que todo caiga a la vez sin un plan", "No necesitan protección contra caídas", "Están exentas de las reglas de grúa"], a: 0, why: "1926.858: retiro de acero. La protección contra caídas sigue aplicando. Las grúas siguen la Subparte CC." },
  { id: "dm-11", category: "demolition", topic: "Incendio en demolición", q: "Un incendio por demolición (corte con soplete, trabajo en caliente) requiere:", choices: ["Prevención de incendios como cualquier trabajo en caliente: extintores, vigía y no cortar en atmósferas explosivas", "Ninguna precaución porque el edificio se viene abajo", "Gasolina para acelerar el corte", "Dejar cilindros de oxígeno en los escombros"], a: 0, why: "1926.850 y la Subparte J siguen aplicando. Los tanques y los químicos residuales explotan." },
  { id: "dm-12", category: "demolition", topic: "Polvo", q: "El polvo de demolición puede contener:", choices: ["Sílice, asbesto, plomo y moho: use agua, EPP y aislamiento", "Solo suciedad molesta que nunca está regulada", "Oxígeno puro", "Helio"], a: 0, why: "Métodos húmedos, aire negativo cuando se exija y protección de los trabajadores. Los vecinos también pueden tener deberes EPA/NESHAP." },
  { id: "rk-01", category: "recordkeeping", topic: "Quién lleva registros", q: "El registro de lesiones/enfermedades de OSHA (Parte 1904) aplica en general a:", choices: ["Empleadores con 11 o más empleados, con algunas exenciones de industrias de bajo peligro", "Todo empleador, incluidos los autoempleados sin trabajadores", "Solo los GC de construcción", "Solo fabricantes con 1,000 empleados"], a: 0, why: "1904.1–2: exenciones de tamaño e industria. Todos los empleadores deben reportar lesiones graves aunque no lleven registros 300." },
  { id: "rk-02", category: "recordkeeping", topic: "Relacionada con el trabajo", q: "Una lesión está relacionada con el trabajo si:", choices: ["Un evento o exposición en el ambiente de trabajo causó o contribuyó a la condición, con excepciones listadas", "Ocurre en cualquier lugar a donde vaya el trabajador 24/7", "Es solo un resfriado contraído del hijo de un compañero", "El trabajador estaba en casa en teletrabajo en un recado personal"], a: 0, why: "1904.5: presunción geográfica con excepciones (comer, tareas personales, resfriados comunes, etc.)." },
  { id: "rk-03", category: "recordkeeping", topic: "Registrable", q: "Una lesión relacionada con el trabajo es registrable si resulta en:", choices: ["Muerte, días de baja, trabajo restringido, transferencia, tratamiento médico más allá de primeros auxilios, pérdida del conocimiento o una lesión significativa diagnosticada por un PLHCP", "Solo muerte", "Una venda", "Una vacuna de tétanos sola en algunos casos de primeros auxilios"], a: 0, why: "1904.7: los criterios de registro. Primeros auxilios vs tratamiento médico se define en 1904.7(b)(5)." },
  { id: "rk-04", category: "recordkeeping", topic: "Primeros auxilios vs tratamiento", q: "¿Cuál es en general primeros auxilios (no registrable por sí solo)?", choices: ["Usar medicamento de venta libre a dosis de venta libre, vendas e inmunizaciones de tétanos", "Medicamento de receta", "Puntos", "Yesos"], a: 0, why: "1904.7(b)(5)(ii) lista tratamientos de primeros auxilios. Los medicamentos de receta, las suturas y los dispositivos que inmovilizan suelen ser tratamiento médico." },
  { id: "rk-05", category: "recordkeeping", topic: "Pinchazo de aguja", q: "Los pinchazos y cortes de punzocortantes contaminados con sangre de otra persona:", choices: ["Son registrables en el registro de OSHA (y en un registro de punzocortantes para BBP) según se especifique", "Nunca son registrables", "Son solo asuntos de HIPAA", "Van solo en el Formulario 301 si nadie sabe"], a: 0, why: "1904.8: pinchazos. Los casos de preocupación de privacidad tienen reglas especiales de registro." },
  { id: "rk-06", category: "recordkeeping", topic: "STS auditivo", q: "Un Cambio umbral estándar relacionado con el trabajo puede ser registrable cuando:", choices: ["El nivel auditivo total del empleado es 25 dB o más por encima del cero audiométrico en las mismas frecuencias, entre otras reglas de 1904.10", "Cualquier zumbido en los oídos", "Un ruido fuerte de una sola vez sin cambio en el audiograma", "Solo si el trabajador está enojado"], a: 0, why: "1904.10: registro de pérdida auditiva. Aplican el ajuste por edad y las reglas de nueva prueba." },
  { id: "rk-07", category: "recordkeeping", topic: "TB", q: "Una infección de tuberculosis relacionada con el trabajo (prueba cutánea positiva después de exposición ocupacional) es:", choices: ["Registrable bajo 1904.11", "Nunca registrable", "Solo un asunto de CDC", "Primeros auxilios"], a: 0, why: "1904.11: TB. El retiro médico y el tratamiento afectan los días de baja/restringidos." },
  { id: "rk-08", category: "recordkeeping", topic: "Casos de privacidad", q: "Para casos de preocupación de privacidad (ciertas lesiones íntimas, enfermedad mental, pinchazos, etc.) el empleador:", choices: ["Puede omitir el nombre del registro 300 y llevar una lista confidencial", "Debe publicar el nombre en el tablón de anuncios", "No puede registrar el caso", "Debe llamar al periódico"], a: 0, why: "1904.29(b)(6)–(9): casos de privacidad. No anote detalles de “caso de privacidad” que identifiquen a la persona en el 300A publicado." },
  { id: "rk-09", category: "recordkeeping", topic: "301", q: "El Formulario 301 (o equivalente) debe completarse dentro de:", choices: ["7 días calendario de recibir información de que ocurrió un caso registrable", "8 horas", "1 año", "Solo el día de la publicación del 300A"], a: 0, why: "1904.29(b)(3): 7 días para el 300 y el 301. El reporte de fatalidad/lesión grave a OSHA sigue siendo 8/24 horas." },
  { id: "rk-10", category: "recordkeeping", topic: "Retención", q: "Los formularios 300, 300A y 301 deben retenerse:", choices: ["5 años después del año al que se relacionan", "30 días", "1 año", "Para siempre en todos los casos"], a: 0, why: "1904.33: 5 años. Actualice el 300 durante ese período si cambia la clasificación del caso." },
  { id: "rk-11", category: "recordkeeping", topic: "Acceso de empleados", q: "Los trabajadores y sus representantes tienen derecho a:", choices: ["Acceder al registro 300 (con protecciones de privacidad) en un tiempo razonable", "Los registros fiscales del empleador", "El expediente investigativo sin redactar de OSHA siempre", "Ningún dato de lesiones"], a: 0, why: "1904.35 / 1904.40: acceso. Proporcione para el final del siguiente día hábil el registro 300 en muchos casos." },
  { id: "rk-12", category: "recordkeeping", topic: "Envío electrónico", q: "Ciertos establecimientos deben enviar electrónicamente datos de lesiones a OSHA:", choices: ["Mediante la Injury Tracking Application de OSHA según lo exija el tamaño/NAICS (300A y en algunos casos datos 300/301)", "Por fax solo al departamento de bomberos local", "Nunca si tienen un registro 300", "Solo si tuvieron una fatalidad"], a: 0, why: "1904.41: envío electrónico. Los umbrales han cambiado: revise las reglas actuales de ITA de OSHA." },
  { id: "rk-13", category: "recordkeeping", topic: "Nuevo vs viejo", q: "Un caso es nuevo si:", choices: ["El empleado no ha experimentado previamente la misma enfermedad relacionada con el trabajo por el mismo tipo de exposición, o una lesión previa sanó y luego se volvió a lesionar, según se especifique", "Cada dolor es siempre un caso nuevo", "Nada es nunca nuevo", "Solo las demandas crean casos"], a: 0, why: "1904.6: nuevo vs recurrente. Las enfermedades crónicas pueden ser complicadas: siga el árbol de decisión." },
  { id: "rk-14", category: "recordkeeping", topic: "Estatus de viaje", q: "Una lesión en un hotel en un viaje de negocios es:", choices: ["En general relacionada con el trabajo si el empleado está allí en interés del empleador, con excepciones para desvíos personales", "Nunca relacionada con el trabajo", "Siempre registrable aunque sea primeros auxilios", "Cubierta solo por compensación para trabajadores, nunca OSHA"], a: 0, why: "1904.5(b)(6): viaje. Una ida a un museo en tiempo personal puede ser una excepción." },
  { id: "rk-15", category: "recordkeeping", topic: "Trabajo desde casa", q: "Las lesiones al trabajar desde casa están relacionadas con el trabajo si:", choices: ["Ocurren mientras el empleado realiza trabajo a cambio de pago o compensación en el área de trabajo del hogar, y se relacionan directamente con el desempeño del trabajo más que con el ambiente del hogar en general", "Cualquier lesión en casa cuenta", "Nunca", "Solo si un supervisor está mirando"], a: 0, why: "1904.5(b)(7): teletrabajo. Tropezar con el perro de la familia mientras no trabaja no está relacionado con el trabajo." },
  { id: "rk-16", category: "recordkeeping", topic: "Trabajadores temporales", q: "Para trabajadores temporales de una agencia de personal, el registro 300 lo lleva en general:", choices: ["El empleador anfitrión que supervisa al trabajador día a día", "Nadie", "OSHA", "El trabajador"], a: 0, why: "1904.31: registra el empleador que supervisa. La agencia de personal igual puede tener deberes. Coordine para que los casos no se cuenten dos veces de forma incorrecta: típicamente registra el empleador que supervisa." },
  { id: "rk-17", category: "recordkeeping", topic: "Contratista", q: "En una obra de construcción, un empleado lesionado de un subcontratista lo registra:", choices: ["El empleador de ese trabajador (el sub), no automáticamente el registro 300 del GC", "Siempre solo el GC", "Siempre el dueño", "Nadie si tiene un 1099"], a: 0, why: "Cada empleador registra a sus propios empleados. Los empleados mal clasificados igual pueden ser empleados bajo la ley." },
  { id: "rk-18", category: "recordkeeping", topic: "Certificar 300A", q: "El 300A debe ser certificado por:", choices: ["Un ejecutivo de la empresa (según se define en 1904.32)", "Cualquier pasante", "El trabajador lesionado", "Un consultor de OSHA"], a: 0, why: "1904.32(b)(3): el funcionario de mayor rango del sitio, o un oficial corporativo, etc. Revise el registro antes de certificar." },
  { id: "rk-19", category: "recordkeeping", topic: "DART", q: "La tasa DART se basa en:", choices: ["Casos de días de baja, restringidos o transferencia", "Solo primeros auxilios", "Casi accidentes", "Horas de capacitación"], a: 0, why: "Se usa en OSHA y en la precalificación de contratistas. La tasa registrable usa todos los registrables." },
  { id: "rk-20", category: "recordkeeping", topic: "Antirrepresalia", q: "El empleador no debe:", choices: ["Tomar represalias contra los trabajadores por reportar lesiones (1904.35 / 11(c))", "Fomentar el reporte", "Proporcionar primeros auxilios", "Publicar el 300A"], a: 0, why: "Los programas de incentivos de seguridad que castigan el reporte son un problema. Las políticas razonables de prueba de drogas tienen límites después de reportes de lesiones." },
  { id: "fa-01", category: "firstaid", topic: "1910.151", q: "Si un lugar de trabajo no está cerca de una clínica u hospital, el empleador debe tener:", choices: ["Personal capacitado para prestar primeros auxilios, y suministros de primeros auxilios", "Ningún plan médico", "Solo un cartel", "El 911 como único plan sin suministros"], a: 0, why: "1910.151(b): personal de primeros auxilios capacitado cuando las enfermerías/clínicas/hospitales no están en proximidad cercana. La construcción 1926.50 es similar." },
  { id: "fa-02", category: "firstaid", topic: "Lavaojos", q: "Donde los ojos o el cuerpo de una persona puedan exponerse a materiales corrosivos lesivos, el empleador debe proporcionar:", choices: ["Instalaciones adecuadas para drenching o enjuague rápido dentro del área de trabajo para uso de emergencia inmediato", "Solo un baño al fondo del pasillo", "Agua embotellada en un camión a 10 minutos", "Una manguera de jardín sin control de presión como única opción siempre"], a: 0, why: "1910.151(c): lavaojos/ducha. ANSI Z358.1 es el consenso (unos 10 segundos / 55 pies es un punto de referencia común) aunque el texto de OSHA dice “dentro del área de trabajo”." },
  { id: "fa-03", category: "firstaid", topic: "Médico en construcción", q: "1926.50 exige:", choices: ["Suministros de primeros auxilios, persona capacitada en ausencia de una enfermería y atención médica inmediata", "Un hospital completo en cada trabajo", "Nada de agua", "Solo una app de primeros auxilios"], a: 0, why: "También números de teléfono de médicos, hospitales y ambulancias publicados. Se exige agua potable bajo 1926.51." },
  { id: "fa-04", category: "firstaid", topic: "Sangre en primeros auxilios", q: "Los respondientes de primeros auxilios con exposición ocupacional a sangre necesitan:", choices: ["Capacitación BBP, EPP y la oferta de vacuna contra hepatitis B", "Ningún guante", "Reencapuchar agujas", "Retrasar la atención hasta el EMS solo, siempre"], a: 0, why: "Atienda al paciente, protéjase. Guantes, protección ocular y una barrera de RCP según se necesite." },
  { id: "fa-05", category: "firstaid", topic: "Choque eléctrico", q: "Después de un choque eléctrico, una vez que la escena es segura:", choices: ["Llame al EMS; la persona puede tener problemas de ritmo cardíaco aunque “se sienta bien”", "Hágalo volver al trabajo de inmediato siempre", "Eche agua a las quemaduras de equipo vivo mientras sigue energizado", "Mueva a la ligera una posible lesión de columna"], a: 0, why: "Las quemaduras eléctricas pueden ser internas. Las víctimas de alto voltaje necesitan atención de trauma. No se convierta en víctima." },
  { id: "fa-06", category: "firstaid", topic: "Primeros auxilios por calor", q: "La primera respuesta a la exhaustión por calor (sudoración fuerte, debilidad, náusea) es:", choices: ["Mover a la sombra, enfriar, hidratar si está consciente; escalar si se convierte en golpe de calor", "Más trabajo extenuante para “sudarlo”", "Tabletas de sal sin agua", "Dejarlo al sol"], a: 0, why: "Conozca la diferencia del golpe de calor (estado mental alterado). En caso de duda, enfríe y llame al 911." },
  { id: "fa-07", category: "firstaid", topic: "Sangrado", q: "Control de sangrado grave:", choices: ["Presión directa con protección de barrera; torniquete si está capacitado y hay sangrado de extremidad que pone en peligro la vida", "Un pañuelo suelto encima", "Solo aspirina", "Esperar y ver"], a: 0, why: "Principios de detener el sangrado. Protéjase de BBP. EMS lo antes posible." },
  { id: "fa-08", category: "firstaid", topic: "Salpicón químico", q: "Salpicón químico a los ojos:", choices: ["Enjuague de inmediato en el lavaojos el tiempo que especifique la SDS (a menudo 15 minutos) manteniendo los párpados abiertos, luego atención médica", "Neutralice ácidos con una base en el ojo", "Frote el ojo", "Espere hasta que termine el turno"], a: 0, why: "Los segundos importan. Quite los lentes de contacto. Lleve la SDS a la sala de emergencias." },
  { id: "fa-09", category: "firstaid", topic: "Botiquín", q: "Los botiquines de primeros auxilios deben:", choices: ["Estar accesibles, surtidos y adecuados a los peligros del lugar de trabajo", "Estar bajo llave en el camión del dueño fuera del sitio", "Estar vencidos como medida de ahorro", "Usarse como caja de herramientas"], a: 0, why: "ANSI/ISEA Z308.1 es una norma común de botiquín. Inspeccione con regularidad. 1926.50 Apéndice A tiene una lista de referencia." },
  { id: "fa-10", category: "firstaid", topic: "AED", q: "Los AED en el lugar de trabajo:", choices: ["No están mandados de forma específica por una sola norma OSHA de AED, pero son una forma reconocida de mejorar la supervivencia; capacite a los usuarios y mantenga el dispositivo", "Están prohibidos por OSHA", "Reemplazan la capacitación de primeros auxilios", "Funcionan sin parches"], a: 0, why: "Buena práctica para sitios grandes y trabajo de alto riesgo. Incluya los AED en el EAP si los tiene." },
  { id: "ps-01", category: "psm", topic: "Norma", q: "La Gestión de seguridad de procesos de químicos altamente peligrosos es:", choices: ["1910.119", "1926.501", "1910.178", "1904.39"], a: 0, why: "El PSM aplica a procesos con químicos listados en o por encima de las cantidades umbral, y a líquidos/gases inflamables de 10,000 libras o más con excepciones." },
  { id: "ps-02", category: "psm", topic: "Umbral", q: "El PSM cubre líquidos o gases inflamables en un proceso en o por encima de:", choices: ["10,000 libras, con excepciones como combustibles de hidrocarburo usados únicamente para el consumo en el lugar de trabajo de esos combustibles", "10 libras siempre", "Cualquier cantidad de gasolina en un camión", "Solo 1 millón de libras"], a: 0, why: "1910.119(a). El Apéndice A lista químicos tóxicos y TQ (p. ej., amoníaco anhidro 10,000 lb, cloro 1,500 lb)." },
  { id: "ps-03", category: "psm", topic: "PSI", q: "La Información de seguridad del proceso incluye:", choices: ["Peligros de los químicos, tecnología del proceso y equipo (incluidos materiales de construcción y P&ID)", "Solo el logo de la empresa", "La nómina", "Tarjetas OSHA 10"], a: 0, why: "1910.119(d): la PSI debe estar completa antes del PHA. Se incluyen los códigos y normas usados para el diseño." },
  { id: "ps-04", category: "psm", topic: "PHA", q: "Un Análisis de peligros del proceso debe:", choices: ["Realizarse por un equipo que incluya al menos a una persona con experiencia en el proceso, usando un método reconocido (What-If, HAZOP, etc.), y actualizarse al menos cada 5 años", "Ser un memorando de una persona", "Ser opcional", "Hacerse solo después de una explosión"], a: 0, why: "1910.119(e): sistema para atender los hallazgos de forma oportuna. Revalidar cada 5 años." },
  { id: "ps-05", category: "psm", topic: "Procedimientos de operación", q: "Los procedimientos de operación deben cubrir:", choices: ["Arranque inicial, normal, temporal, paro de emergencia, operaciones de emergencia, paro normal y arranque después de una parada, más los sistemas de seguridad y sus funciones", "Solo el turno de noche", "Cómo saltarse los interbloqueos", "Solo los horarios de descanso"], a: 0, why: "1910.119(f): los procedimientos deben estar actuales, claros y certificados anualmente como actuales." },
  { id: "ps-06", category: "psm", topic: "MOC", q: "La Gestión del cambio se exige para:", choices: ["Cambios a químicos del proceso, tecnología, equipo y procedimientos (no “reemplazo en especie”)", "Cambiar un foco que es verdaderamente reemplazo en especie", "El menú de la cafetería", "El color de pintura en la oficina"], a: 0, why: "1910.119(l): MOC antes del cambio. Informe y capacite a los empleados afectados. Actualice la PSI y los procedimientos." },
  { id: "ps-07", category: "psm", topic: "MI", q: "La Integridad mecánica aplica a:", choices: ["Recipientes a presión, tanques de almacenamiento, tubería, sistemas de alivio, paro de emergencia, controles y bombas que manejan químicos altamente peligrosos", "Sillas de oficina", "El estacionamiento", "Solo herramientas de mano"], a: 0, why: "1910.119(j): procedimientos escritos, capacitación, inspección/prueba según RAGAGEP y corrección de deficiencias." },
  { id: "ps-08", category: "psm", topic: "Trabajo en caliente PSM", q: "El trabajo en caliente en un área de proceso PSM requiere:", choices: ["Un permiso de trabajo en caliente (1910.119(k) y 1910.252)", "Ningún permiso si trabaja para la planta", "Soldar siempre en líneas vivas", "Solo un casco"], a: 0, why: "Los permisos documentan la prevención de incendios y el aislamiento. Muchos incidentes empiezan como soldadura “rutinaria”." },
  { id: "ps-09", category: "psm", topic: "Investigación de incidentes", q: "Las investigaciones de incidentes PSM deben comenzar:", choices: ["Tan pronto como sea posible, pero no más tarde de 48 horas después del incidente", "Dentro de 1 año", "Nunca si nadie murió", "Solo si OSHA ya está en el sitio"], a: 0, why: "1910.119(m): informe, recomendaciones y compartir con contratistas y empleados cuyo trabajo sea pertinente." },
  { id: "ps-10", category: "psm", topic: "Contratistas PSM", q: "Los empleadores anfitriones deben:", choices: ["Informar a los empleadores contratistas de los peligros conocidos de incendio, explosión o tóxicos relacionados con el trabajo del contratista y el proceso, y del plan de emergencia", "Ocultar los peligros del proceso a los contratistas", "Asumir que los contratistas lo saben todo", "Saltar la orientación"], a: 0, why: "1910.119(h): evalúe los programas de seguridad de los contratistas, el desempeño periódico y un registro de lesiones/enfermedades de empleados contratados relacionado con el trabajo del contratista en las áreas de proceso." },
  { id: "ps-11", category: "psm", topic: "PSSR", q: "La revisión de seguridad previa al arranque se exige para:", choices: ["Instalaciones nuevas e instalaciones modificadas cuando la modificación es lo bastante significativa para exigir un cambio en la PSI", "Cada cafetera", "Solo actualizaciones de software en RR. HH.", "Resellar el estacionamiento"], a: 0, why: "1910.119(i): el PSSR confirma que la construcción está de acuerdo con el diseño, que hay procedimientos y que se hizo la capacitación." },
  { id: "ps-12", category: "psm", topic: "Secretos comerciales", q: "La información de PSM necesaria para PHA, procedimientos y contratistas:", choices: ["Aun así debe proporcionarse; los acuerdos de confidencialidad pueden proteger secretos comerciales sin bloquear la información de seguridad", "Puede retenerse por completo del equipo de PHA", "Está prohibida", "Va solo a OSHA, nunca a los trabajadores"], a: 0, why: "1910.119(p): los secretos comerciales no pueden impedir el cumplimiento." },
  { id: "ps-13", category: "psm", topic: "Emergencia PSM", q: "Las instalaciones PSM deben tener un plan de acción de emergencia que cumpla 1910.38, y si van a responder a una liberación:", choices: ["También aplica HAZWOPER 1910.120(q)", "Ningún plan extra", "Solo una cuenta de Twitter", "La evacuación está prohibida"], a: 0, why: "1910.119(n): planificación de emergencia. Coordine con los respondientes locales (LEPC)." },
  { id: "ps-14", category: "psm", topic: "Auditoría de cumplimiento", q: "Las auditorías de cumplimiento PSM se exigen al menos cada:", choices: ["3 años", "10 años", "6 meses", "Nunca"], a: 0, why: "1910.119(o): al menos una persona conocedora del proceso en el equipo de auditoría. Retenga los dos informes más recientes." },
  { id: "ps-15", category: "psm", topic: "Participación de empleados", q: "El empleador debe tener un plan escrito para:", choices: ["La participación de los empleados en el PHA y otros elementos de PSM", "Mantener a los operadores fuera de las juntas de seguridad", "Solo las multas", "Buzones de sugerencias opcionales como único elemento"], a: 0, why: "1910.119(c): consulte con los empleados y sus representantes. Proporcione acceso al PHA y a los informes de incidentes." },
  { id: "tl-01", category: "tools", topic: "Condición", q: "Las herramientas de mano y eléctricas deben:", choices: ["Mantenerse en condición segura; las herramientas dañadas se retiran de servicio", "Usarse hasta que fallen en la mano de alguien", "Hacerse en casa de varilla siempre", "Quedar sin tierra aunque estén diseñadas para tierra"], a: 0, why: "1926.300 / 1910.242: inspeccione. Los cinceles con cabeza de hongo y los mangos rajados causan lesiones." },
  { id: "tl-02", category: "tools", topic: "Cabeza de hongo", q: "Una cabeza de hongo en un cincel o martillo:", choices: ["Puede astillarse y golpear los ojos; repare la cabeza o reemplace la herramienta", "Es una señal de calidad", "Mejora el golpe", "No necesita protección ocular"], a: 0, why: "1926.301: mantenga las herramientas de impacto libres de cabezas de hongo. Use protección ocular." },
  { id: "tl-03", category: "tools", topic: "Sierra circular", q: "Una sierra circular portátil debe tener:", choices: ["Un resguardo superior y un resguardo inferior retráctil que vuelve a cubrir la hoja", "Ningún resguardo para cortes de inmersión como costumbre", "Una hoja con dientes faltantes para ir más rápido", "El cordón cortado corto"], a: 0, why: "1926.304 / 1910.243: resguardos. No acuñe el resguardo inferior abierto." },
  { id: "tl-04", category: "tools", topic: "Neumático", q: "Las mangueras neumáticas deben:", choices: ["Asegurarse para evitar que se desconecten por accidente y den latigazos", "Usarse como cuerdas de saltar", "Sujetarse por un compañero en el acople durante el uso", "Clasificarse por debajo de la presión del compresor"], a: 0, why: "1926.302(b): clips/retenedores de seguridad en las conexiones. Cadenas antlatigazo en mangueras más grandes." },
  { id: "tl-05", category: "tools", topic: "Aire para limpiar", q: "El aire comprimido usado para limpiar no debe exceder:", choices: ["30 psi, y entonces solo con resguardo eficaz de virutas y EPP", "90 psi siempre", "200 psi", "Ningún límite"], a: 0, why: "1910.242(b): 30 psi para limpiar. Nunca use aire comprimido para soplar ropa en el cuerpo: peligro de embolia. Las reglas de sílice restringen aún más el soplado de polvo." },
  { id: "tl-06", category: "tools", topic: "Cargas de pólvora", q: "Las herramientas de carga explosiva:", choices: ["No deben cargarse hasta justo antes de disparar; las herramientas sin usar se dejan descargadas; nunca se apuntan a nadie", "Pueden dejarse cargadas en una caja de herramientas", "Son juguetes", "No necesitan protección auditiva"], a: 0, why: "1926.302(e): operadores capacitados, distintas cargas para distintos materiales y un procedimiento de fallo de disparo (espere, luego retire con cuidado)." },
  { id: "tl-07", category: "tools", topic: "Gatos", q: "Los gatos deben:", choices: ["Estar clasificados para la carga, colocarse sobre una base firme y apuntalarse según se exija; no exceda la capacidad nominal", "Apilarse uno sobre otro a la ligera", "Usarse siempre como apoyo permanente sin bloqueo", "Patearse de debajo de una carga"], a: 0, why: "1926.305 / 1910.244: bloquee la carga. Los gatos hidráulicos pueden asentarse poco a poco." },
  { id: "tl-08", category: "tools", topic: "Rueda abrasiva portátil", q: "Las esmeriladoras portátiles necesitan:", choices: ["Resguardos colocados para desviar fragmentos; ruedas emparejadas a las RPM y el tipo (centro deprimido vs corte)", "Resguardos quitados siempre para un mejor ángulo", "Ruedas de RPM desconocidas", "Esmerilado de lado en una rueda de corte no diseñada para ello"], a: 0, why: "1910.243 / 1926.303: resguardos. Las ruedas de corte no son para esmerilar de lado." },
  { id: "tl-09", category: "tools", topic: "Herramientas GFCI", q: "Las herramientas con cordón en obras de construcción en general necesitan:", choices: ["Protección GFCI en el circuito", "Adaptadores de dos patas (cheater)", "Regletas domésticas en cadena como el servicio", "Ninguna inspección"], a: 0, why: "1926.404(b). Inspeccione los cordones a diario. Alivio de tensión en los enchufes." },
  { id: "tl-10", category: "tools", topic: "Herramientas de combustible", q: "Las herramientas de combustible en interiores:", choices: ["Crean peligros de CO e incendio; ventile y apague para recargar después de enfriar según se exija", "Son más seguras que las eléctricas", "Pueden recargarse mientras corren", "No necesitan un extintor cerca"], a: 0, why: "1926.302(c): detenga los motores para recargar; no fume. El CO mata en sótanos y tráileres." },
  { id: "tl-11", category: "tools", topic: "Fallo de disparo de pólvora", q: "Después de un fallo de disparo de carga explosiva, el operador debe:", choices: ["Seguir al fabricante: típicamente mantener la herramienta en posición de disparo el tiempo especificado y luego descargar con cuidado", "Mirar por el cañón", "Golpearla con un martillo", "Pasarla cargada a un ayudante"], a: 0, why: "1926.302(e)(6): espere al menos 30 segundos en algunos procedimientos (revise el manual de la herramienta). Trátela como viva." },
  { id: "tl-12", category: "tools", topic: "Hidráulico", q: "Los gatos y las herramientas hidráulicas pueden:", choices: ["Inyectar fluido bajo la piel (lesión por inyección): una emergencia médica incluso por una fuga del tamaño de un alfiler", "Solo causar resbalones", "Nunca fallar", "Revisarse pasando la mano por las mangueras bajo presión"], a: 0, why: "Use cartón para encontrar fugas, no la piel. Las lesiones por inyección se ven pequeñas y destruyen tejido." },
  { id: "sw-01", category: "stairways", topic: "Subparte X", q: "Las escaleras fijas y de mano de construcción están en:", choices: ["1926 Subparte X", "1926 Subparte P", "1910.120", "1926 Subparte CC"], a: 0, why: "1926.1050–1060. Las escaleras de industria general son 1910.25–26." },
  { id: "sw-02", category: "stairways", topic: "Cuándo se exige", q: "Se exige una escalera fija o de mano en los puntos de acceso que tienen un desnivel de:", choices: ["19 pulgadas o más", "solo 4 pies", "solo 10 pies", "solo 30 pulgadas siempre"], a: 0, why: "1926.1051(a): 19 pulgadas. Las rampas son otra opción." },
  { id: "sw-03", category: "stairways", topic: "Escaleras de charola", q: "Las charolas de escalera que se llenarán de concreto deben:", choices: ["Llenarse hasta el tope de la charola, o dotarse de madera temporal u otro material hasta llenarse, salvo durante la construcción de la escalera", "Dejarse como charolas abiertas para que los trabajadores trepen el refuerzo", "Cubrir solo con visqueen", "Usarse solo por montadores de acero sin relleno"], a: 0, why: "1926.1052(b)(2): no use escaleras de metal esqueleto sin relleno de charola o equivalente." },
  { id: "sw-04", category: "stairways", topic: "Descansos", q: "Las escaleras fijas deben tener descansos de al menos:", choices: ["30 pulgadas en la dirección de viaje y 22 pulgadas de ancho, cada 12 pies de subida vertical o menos", "12 pulgadas cuadradas", "Nunca descansos", "Solo en la parte superior"], a: 0, why: "1926.1052(a)(1) y (a)(4): tamaño del descanso y límites de subida vertical." },
  { id: "sw-05", category: "stairways", topic: "Variación", q: "La altura de contrahuella y la profundidad de huella en una escalera fija no deben variar más de:", choices: ["1/4 de pulgada en cualquier sistema de escalera", "2 pulgadas", "1 pulgada", "Ningún límite"], a: 0, why: "1926.1052(a)(3): variación máxima de 1/4 de pulgada. Las escaleras desiguales causan caídas." },
  { id: "sw-06", category: "stairways", topic: "Barandales de escalera", q: "Las escaleras fijas con cuatro o más contrahuellas o que suben más de 30 pulgadas necesitan:", choices: ["Al menos un pasamanos y un sistema de barandal de escalera a lo largo de cada lado o borde sin protección", "Ningún barandal durante la construcción", "Cinta de precaución", "Una soga a 60 pulgadas"], a: 0, why: "1926.1052(c): altura de barandales de escalera 36–37 pulgadas (según se especifique para mediados de 2010 vs más viejos), pasamanos 30–37 pulgadas. Conozca el texto actual para su fecha de instalación." },
  { id: "sw-07", category: "stairways", topic: "Escaleras temporales", q: "Las escaleras temporales deben:", choices: ["Tener al menos 22 pulgadas de ancho, con ángulos especificados, y no ser una colección de cajas", "Hacerse de tarimas apiladas", "Ser más empinadas de 70 grados", "Quedar sin luz"], a: 0, why: "1926.1052(a)(2): ancho mínimo de 22 pulgadas. Rango de ángulo 30–50 grados para escaleras estándar en GI; la construcción tiene una práctica similar de ángulo seguro." },
  { id: "sw-08", category: "stairways", topic: "Espiral", q: "Las escaleras de caracol en construcción:", choices: ["En general se permiten solo para acceso limitado especial (tanques, torres) donde una escalera convencional no es práctica, con reglas extra", "Se prefieren para todos los edificios", "No necesitan pasamanos", "Pueden ser espirales de varilla sin luz"], a: 0, why: "1926.1052(a)(5): uso limitado de escaleras de caracol." },
  { id: "sw-09", category: "stairways", topic: "Escaleras resbalosas", q: "Las huellas de escalera deben:", choices: ["Ser razonablemente antideslizantes y mantenerse libres de hielo, lodo y escombros", "Engrasarse para desmolde como superficie de circulación", "Usarse para almacenar madera", "Ser de contrahuella abierta siempre sin consideración"], a: 0, why: "Orden y limpieza más la norma de escaleras. El hielo en charolas de metal es una caída clásica." },
  { id: "sw-10", category: "stairways", topic: "Escalera de mano vs fija", q: "Cuando una escalera la usarían muchos trabajadores con herramientas, la mejor opción suele ser:", choices: ["Una escalera fija o torre de escalera debidamente construida en lugar de una sola escalera portátil", "Una soga", "Saltar", "Un montón de tierra"], a: 0, why: "Las escaleras de mano son para acceso limitado. Las torres de escalera de andamio existen por una razón." },
  { id: "gi-01", category: "intro", topic: "OSH Act 5(a)(2)", q: "La Sección 5(a)(2) de la OSH Act exige que el empleador:", choices: ["Cumpla las normas de seguridad y salud ocupacional promulgadas bajo la Ley", "Pague a los inspectores de OSHA", "Proporcione autos de la empresa", "Ofrezca opciones sobre acciones"], a: 0, why: "5(a)(1) es el deber general; 5(a)(2) es cumplir las normas. Los trabajadores también tienen deberes 5(b)." },
  { id: "gi-02", category: "intro", topic: "Deber del empleado", q: "La Sección 5(b) exige que cada empleado:", choices: ["Cumpla las normas y reglas de OSHA aplicables a sus propias acciones y conducta", "Inspeccione toda la planta solo", "Pague todo el EPP", "Nunca reporte peligros"], a: 0, why: "Los trabajadores deben seguir las reglas. Eso no transfiere la responsabilidad primaria del empleador." },
  { id: "gi-03", category: "intro", topic: "NIOSH", q: "NIOSH es:", choices: ["Una agencia de investigación (CDC) que desarrolla límites de exposición recomendados e investiga peligros; no emite citaciones de OSHA", "La rama de cumplimiento de OSHA", "Un plan estatal", "Un sindicato"], a: 0, why: "REL de NIOSH vs PEL de OSHA. Las Evaluaciones de peligros para la salud (HHE) son herramientas de NIOSH." },
  { id: "gi-04", category: "intro", topic: "BLS", q: "Las estadísticas nacionales de lesiones en el trabajo las publica:", choices: ["La Oficina de Estadísticas Laborales (SOII), usando datos del registro de OSHA y encuestas", "Solo FEMA", "El censo de solo caídas fatales de construcción", "Wikipedia"], a: 0, why: "BLS SOII y CFOI. OSHA usa los datos para la focalización." },
  { id: "gi-05", category: "intro", topic: "VPP", q: "Los Programas de protección voluntaria (VPP) de OSHA:", choices: ["Reconocen sitios de trabajo con sistemas sobresalientes de seguridad y salud; no son un sustituto del cumplimiento", "Eximen a los empleadores de todas las normas", "Se exigen para OSHA 30", "Reemplazan la compensación para trabajadores"], a: 0, why: "Los sitios Star y Merit igual deben seguir la ley. Las inspecciones son distintas pero no nulas." },
  { id: "gi-06", category: "intro", topic: "Énfasis nacional", q: "Un Programa Nacional de Énfasis (NEP) significa que OSHA:", choices: ["Focalizará inspecciones en un peligro definido (p. ej., calor, sílice, zanjas, almacenes)", "Detendrá todas las demás inspecciones", "Solo escribirá cartas", "Prohibirá la industria"], a: 0, why: "Los NEP impulsan inspecciones programadas. El NEP de zanjas es muy conocido en construcción." },
  { id: "gi-07", category: "intro", topic: "Peligro inminente", q: "Si un inspector encuentra peligro inminente, va a:", choices: ["Pedir al empleador que abata de inmediato y retire a los trabajadores; puede solicitar una orden judicial si el empleador se niega", "Volver el año siguiente", "Solo entregar un folleto", "Arrestar al trabajador"], a: 0, why: "El inspector no cierra el trabajo personalmente como un oficial de policía en la mayoría de los casos, pero las herramientas legales son rápidas. Los trabajadores deben salir del peligro." },
  { id: "gi-08", category: "intro", topic: "Conferencia de cierre", q: "En la conferencia de cierre, OSHA discute:", choices: ["Infracciones aparentes, corrección y derechos del empleador/empleado", "Las vacaciones del inspector", "Solo buenas noticias", "Elecciones sindicales"], a: 0, why: "Las citaciones llegan después por escrito. Puede hacer preguntas y proporcionar documentos extra." },
  { id: "gi-09", category: "intro", topic: "Conferencia informal", q: "Después de una citación, un empleador puede solicitar una conferencia informal:", choices: ["Por lo general dentro del período de 15 días hábiles de impugnación, para discutir multas y corrección con el director de área", "Solo después de 90 días", "Nunca", "Solo primero en un tribunal federal"], a: 0, why: "Las conferencias informales pueden llevar a acuerdos. Impugnar es un camino legal aparte hacia la Review Commission." },
  { id: "gi-10", category: "intro", topic: "OSHRC", q: "Las citaciones impugnadas las oye:", choices: ["La Occupational Safety and Health Review Commission, una agencia independiente", "NIOSH", "El mismo inspector de OSHA como juez", "El departamento local de construcción"], a: 0, why: "Los ALJ de OSHRC oyen los casos. Las apelaciones pueden ir a la Commission y luego a tribunales federales." },
  { id: "fp-37", category: "fallProtection", topic: "Tamaño del hueco", q: "En construcción, un hueco es un espacio o vacío de 2 pulgadas o más en su dimensión menor en un piso, techo u otra superficie de circulación. La protección contra caídas para huecos se exige a:", choices: ["6 pies o más hasta el nivel inferior (y protección contra objetos que caen según se especifique)", "Solo a 15 pies", "Nunca si es de 2 pulgadas", "Solo para huecos de 12 pulgadas"], a: 0, why: "Definiciones de 1926.500 y 1926.501(b)(4). Los huecos pequeños igual tropiezan y dejan caer herramientas. Los más grandes se tragan a las personas." },
  { id: "fp-38", category: "fallProtection", topic: "Caída en excavación", q: "Las pasarelas sobre excavaciones en general necesitan barandales cuando la pasarela está:", choices: ["A 6 pies o más sobre el nivel inferior", "A 2 pies por encima", "Siempre exenta", "Solo a 20 pies"], a: 0, why: "1926.501(b)(7) y 1926.651(l): pasarelas sobre excavaciones. También mantenga el material excavado atrás." },
  { id: "fp-39", category: "fallProtection", topic: "Cimbra", q: "Los empleados en cimbra y acero de refuerzo en general necesitan protección contra caídas a:", choices: ["6 pies", "15 pies siempre como el montaje de acero", "30 pies", "Nunca"], a: 0, why: "1926.501(b)(5): cimbra y acero de refuerzo a 6 pies. Los sistemas de posicionamiento son comunes en muros de varilla con PFAS según se exija." },
  { id: "fp-40", category: "fallProtection", topic: "Techado residencial empinado", q: "Los techadores en un techo empinado necesitan:", choices: ["Protección convencional contra caídas (barandales, redes o PFAS), no un sistema de línea de advertencia", "Solo protectores de deslizamiento como único sistema OSHA después de los cambios residenciales de 2017", "Ninguna protección bajo 25 pies", "Un monitor a 100 pies como único sistema"], a: 0, why: "Las líneas de advertencia son para pendiente baja. Techos empinados: sistemas convencionales. Los monitores de seguridad tienen límites estrictos en pendiente baja con líneas de advertencia." },
  { id: "fp-41", category: "fallProtection", topic: "Vigía", q: "Un vigía de seguridad usado con un sistema de línea de advertencia debe ser:", choices: ["Una persona competente en el mismo techo, a la vista y a voz, sin otras funciones que le quiten atención del papel de vigía", "Cualquiera en el suelo con un teléfono", "Un peón colgando armaduras al mismo tiempo", "Opcional si tiene cinta de precaución"], a: 0, why: "1926.502(h): deberes del vigía. Solo se usa en techos de pendiente baja como parte de los sistemas especificados." },
  { id: "fp-42", category: "fallProtection", topic: "Cubiertas de tráfico", q: "Las cubiertas de huecos en calzadas o que soportan vehículos deben:", choices: ["Ser capaces de soportar 2 veces la carga máxima de eje del vehículo más grande esperado", "Madera contrachapada de cualquier grosor", "Cerca de nieve", "Cinta de precaución"], a: 0, why: "1926.502(i)(3)–(4): 2× carga peatonal para cubiertas de empleados; 2× carga de eje para cubiertas de vehículos." },
  { id: "fp-43", category: "fallProtection", topic: "Barandal superior de andamio", q: "La altura del barandal de andamio cuando no se usa PFAS es en general:", choices: ["38 a 45 pulgadas para andamios apoyados fabricados/usados bajo las reglas actuales (revise 1926.451(g)(4) para la división por fecha de instalación)", "21 pulgadas", "60 pulgadas", "12 pulgadas"], a: 0, why: "1926.451(g)(4): 38–45 pulgadas para andamios fabricados después del 1 de enero de 2000 en muchos casos; más viejos 36–45. Conozca sus marcos." },
  { id: "fp-44", category: "fallProtection", topic: "Riostra en cruz como barandal", q: "La riostra en cruz de un andamio puede contar como barandal intermedio o superior solo cuando:", choices: ["El punto de cruce está en el rango de altura requerido para ese miembro", "Siempre, a cualquier altura", "Nunca", "Solo si está pintada"], a: 0, why: "1926.451(g)(4)(xv): el punto de cruce debe estar a 20–30 pulgadas para un equivalente de barandal intermedio, o 38–48 pulgadas para un equivalente de superior, y los marcos de extremo igual necesitan un riel del otro lado según se especifique." },
  { id: "fp-45", category: "fallProtection", topic: "Pump jack", q: "Los andamios pump-jack tienen:", choices: ["Reglas específicas 1926.452(j) que incluyen el banco de trabajo como barandal superior en algunos montajes y protección contra caídas a 10 pies", "Ninguna protección contra caídas nunca", "Lo mismo que una plataforma de brazo", "Altura ilimitada sin amarres"], a: 0, why: "Los postes deben asegurarse. La protección contra caídas sigue aplicando. No sobrecargue los bancos de trabajo." },
  { id: "ex-23", category: "excavation", topic: "Banquetas", q: "Las banquetas no son una opción en:", choices: ["Suelo Tipo C (el Apéndice B no permite banquetas en Tipo C)", "Tipo A", "Tipo B en algunos datos tabulados", "Roca estable"], a: 0, why: "El Tipo C solo puede inclinarse (o apoyarse/escudarse), no hacerse banquetas, bajo los datos tabulados de OSHA." },
  { id: "ex-24", category: "excavation", topic: "En capas", q: "En suelos en capas, en general clasifique e incline para:", choices: ["La capa más débil (menos estable) que afecta la excavación", "Solo la pulgada superior", "Tipo A si hay algo de arcilla", "Lo que sea más rápido"], a: 0, why: "Una capa débil bajo una costra es un montaje clásico de colapso. Clasifique de forma conservadora." },
  { id: "ex-25", category: "excavation", topic: "Fisurado", q: "El suelo fisurado no puede ser:", choices: ["Tipo A", "Tipo C", "Escudado", "Inclinado"], a: 0, why: "Apéndice A: fisurado, previamente disturbado o sujeto a vibración: no Tipo A." },
  { id: "ex-26", category: "excavation", topic: "Prueba del pulgar", q: "La prueba de penetración del pulgar es un:", choices: ["Método de campo para ayudar a estimar la resistencia a la compresión no confinada de suelo cohesivo", "Sustituto legal de un PE a 25 pies", "Prueba solo para arena", "Exigido a diario por nombre en cada zanja"], a: 0, why: "Apéndice A: penetrómetro de bolsillo, veleta de corte y prueba del pulgar. También pruebas de plasticidad y secado. Documente la clasificación." },
  { id: "ex-27", category: "excavation", topic: "Roca estable", q: "La roca estable es:", choices: ["Mineral sólido natural que puede excavarse con lados verticales y permanecer intacto mientras está expuesto", "Arcilla dura", "Relleno compactado", "Fresado de asfalto"], a: 0, why: "Pocas obras tienen verdadera roca estable. En caso de duda, proteja." },
  { id: "ex-28", category: "excavation", topic: "Datos tabulados", q: "Los datos tabulados de los fabricantes para escudos deben:", choices: ["Estar en el sitio y seguirse, incluidas las clasificaciones de profundidad y los tipos de suelo", "Quedarse en el patio", "Ser opcionales si la caja se ve fuerte", "Usarse más allá de la clasificación si trabaja rápido"], a: 0, why: "1926.652(c)(2): datos tabulados. Un PE diseña cuando sale de los datos." },
  { id: "ex-29", category: "excavation", topic: "Rampa estructural", q: "Las rampas de tierra usadas para acceso deben:", choices: ["Ser uniformes y tener una superficie en la que los trabajadores no resbalen; las rampas estructurales para equipo necesitan diseño de PE", "Cortarse a 60 grados", "Usarse como almacenamiento de material excavado", "Tener solo el ancho de una bota"], a: 0, why: "1926.651(c): distinga rampas de empleados vs rampas de vehículos." },
  { id: "ex-30", category: "excavation", topic: "Cruce", q: "Las pasarelas sobre zanjas deben:", choices: ["Estar equipadas con barandales si están a 6 pies o más sobre el nivel inferior", "Ser un solo 2x10 sin barandales a 10 pies", "Ser opcionales si los trabajadores saltan", "Hacerse de cinta de precaución"], a: 0, why: "1926.651(l): pasarelas y puentes. Barandales según la Subparte M." },
  { id: "el-26", category: "electrical", topic: "GFCI mensual", q: "Los dispositivos GFCI deben:", choices: ["Probarse (test/reset) según especifique el fabricante: a menudo antes del uso o mensualmente", "Nunca probarse para que duren más", "Anularse con un cheater", "Usarse como el dispositivo de bloqueo"], a: 0, why: "Un GFCI que no dispara es una falsa sensación de seguridad. Los GFCI portátiles se maltratan en las obras." },
  { id: "el-27", category: "electrical", topic: "Colores asegurados", q: "Las pruebas trimestrales del AEGCP a menudo se identifican por:", choices: ["Un sistema de cinta con código de color por trimestre (ejemplo: blanco, verde, rojo, naranja: siga el programa escrito)", "Pintar todo el cordón", "Ninguna marca", "Un nudo en el cordón"], a: 0, why: "1926.404(b)(1)(iii): marcado para indicar la prueba más reciente. Los programas varían por color: conozca el suyo." },
  { id: "el-28", category: "electrical", topic: "Bomba de concreto mojado", q: "Una bomba de concreto con pluma de colocación cerca de líneas eléctricas es:", choices: ["Un peligro de electrocución como una grúa: mantenga distancia o desenergice", "Segura porque el concreto es una tierra", "Exenta de las reglas de 10 pies", "Solo un peligro de golpes"], a: 0, why: "Las plumas conducen. Los vigías y observadores dedicados salvan vidas." },
  { id: "el-29", category: "electrical", topic: "811 subterráneo", q: "Antes de excavar, llamar al 811:", choices: ["Inicia el proceso de localización de muchos servicios; espere el tiempo requerido y respete las marcas", "Reemplaza siempre un localizador privado para líneas del sitio", "Es opcional si “conoce el sitio”", "Significa que puede usar una retroexcavadora sobre las marcas"], a: 0, why: "Cave a mano en la zona de tolerancia. Las líneas privadas (iluminación del sitio, lazos de incendio) pueden necesitar un localizador privado." },
  { id: "el-30", category: "electrical", topic: "Panel temporal", q: "Los paneles de energía temporal en obras de construcción deben tener:", choices: ["Tapas, breakers adecuados, alivio de tensión y GFCI donde se exija; no partes vivas abiertas", "Barras colectoras descubiertas para fácil acceso", "“Colas” de extensión doméstica como el servicio", "Ninguna identificación de circuitos"], a: 0, why: "1926.404–405: gabinetes, accesorios y cordones de uso extra pesado para lugares mojados." },
  { id: "hh-27", category: "health", topic: "Médico de sílice", q: "La vigilancia médica de sílice se exige en general cuando:", choices: ["El trabajador estará expuesto en o por encima del nivel de acción 30 o más días al año", "Corta concreto una vez", "Usa sombrero", "Nunca en construcción"], a: 0, why: "1926.1153(h): médico cada 3 años (o según recomiende el PLHCP) incluido tamizaje de TB y evaluación pulmonar." },
  { id: "hh-28", category: "health", topic: "Berilio", q: "El berilio (1910.1024 / 1926.1124) es una preocupación en:", choices: ["Ciertos metales, aeroespacial y algunas cerámicas: puede causar enfermedad crónica por berilio", "Solo polvo de madera blanda", "Papel de oficina", "Agua"], a: 0, why: "PEL muy bajos. Esmerilar cobre-berilio necesita controles estrictos." },
  { id: "hh-29", category: "health", topic: "Cadmio", q: "El humo de cadmio de soldar o soldar fuerte sobre acero chapado es:", choices: ["Altamente tóxico para riñones y pulmones; use ventilación y la norma de cadmio cuando aplique", "Una vitamina", "Solo un peligro de incendio", "Inofensivo si no puede olerlo"], a: 0, why: "1910.1027. La “soldadura de plata” y los recubrimientos pueden contener cadmio. No suelde en un cuarto cerrado." },
  { id: "hh-30", category: "health", topic: "Moho", q: "OSHA no tiene un PEL de moho, pero:", choices: ["La Cláusula de deber general y las reglas de saneamiento/ventilación igual pueden aplicar; arregle la humedad y proteja a los trabajadores durante la remediación", "El moho nunca es un asunto de OSHA", "El cloro sin EPP siempre se exige", "Solo EPA cita el moho"], a: 0, why: "Edificios dañados por agua: EPP, contención y remediación competente. Los asmáticos tienen mayor riesgo." },
  { id: "hh-31", category: "health", topic: "Nanomateriales", q: "Los nanomateriales de ingeniería deben:", choices: ["Tratarse con precaución: use contención, HEPA y evite el barrido en seco; siga NIOSH y la SDS", "Manejarse como arena sin controles", "Comerse para probar la toxicidad", "Soplarse con aire comprimido"], a: 0, why: "Peligro emergente. Los nanotubos de carbono tienen REL de NIOSH. No improvise." },
  { id: "hh-32", category: "health", topic: "MP de diésel", q: "El escape de diésel en túneles, talleres y almacenes:", choices: ["Contiene partículas y gases; ventile, restrinja el ralentí y considere postratamiento", "Es saludable", "Solo huele mal", "Está desregulado en todo sentido"], a: 0, why: "MSHA tiene reglas de DPM en minas. OSHA usa PEL para componentes (NO2, CO, etc.) y el Deber general para la mezcla. Peligro de cáncer." },
  { id: "pp-28", category: "ppe", topic: "Ropa FR", q: "Se exige ropa resistente a la flama cuando:", choices: ["La evaluación del empleador (o una norma como 1910.269 / 1926.960 para eléctrico, o soldadura/metal fundido) identifica un peligro de incendio relámpago o arco que la FR mitigará", "Trabaja al aire libre solo en invierno", "Siempre para egresados de OSHA 10", "Nunca en industria general"], a: 0, why: "NFPA 70E y 2112 son normas de consenso a las que OSHA a menudo mira. Algodón vs poliéster: los sintéticos se derriten." },
  { id: "pp-29", category: "ppe", topic: "Clasificación de arco", q: "Un ATPV o EBT en ropa FR es:", choices: ["La clasificación de arco en cal/cm² usada para seleccionar ropa para la energía incidente", "Una talla de moda", "La clase del casco", "El NRR de ruido"], a: 0, why: "Empareje la ropa al estudio de destello de arco. Una camisa de 4 cal no basta para una tarea de 25 cal." },
  { id: "pp-30", category: "ppe", topic: "Chalecos salvavidas", q: "Al trabajar sobre o cerca del agua donde existe un peligro de ahogamiento, las reglas de construcción exigen:", choices: ["Chalecos/chaquetas salvavidas aprobados por la Guardia Costera de EE. UU., aros salvavidas y un bote según se especifica en 1926.106", "Solo un casco", "Lecciones de natación como único control", "Ninguna flotación si sabe nadar"], a: 0, why: "1926.106: PFD, 90 pies de cabo en aros a intervalos de 200 pies, y un bote donde el agua es demasiado peligrosa para solo aros." },
  { id: "lo-23", category: "loto", topic: "Caja de grupo", q: "Un bloqueo de grupo con caja de candados suele funcionar:", choices: ["Con el candado de cada trabajador en la caja que guarda las llaves de los candados del equipo, de modo que no se pueda restaurar la energía hasta que se quite el último candado personal", "Con una llave compartida bajo un tapete", "Con etiquetas sin candados siempre", "Con el supervisor guardando todas las llaves personales"], a: 0, why: "El equipo permanece aislado. Los candados personales en la caja equivalen a protección personal." },
  { id: "lo-24", category: "loto", topic: "Complejo", q: "El LOTO complejo (muchos puntos de aislamiento) a menudo usa:", choices: ["Un procedimiento escrito, un empleado autorizado principal y la verificación de que cada punto está aislado", "Solo la memoria", "Un solo breaker para toda una planta siempre", "Ninguna etiqueta"], a: 0, why: "Nota de 1910.147(f)(4) / directiva de OSHA: bloqueo de grupo de sistemas complejos. Verifique. Cuentan las bridas ciegas y las válvulas." },
  { id: "lo-25", category: "loto", topic: "Apertura de línea", q: "Abrir una línea de proceso (line breaking) es:", choices: ["Un servicio que en general requiere aislamiento, LOTO y controles de químicos residuales: no “solo un trabajo de llave”", "Siempre exento de LOTO", "Solo un asunto de HazCom", "Seguro si la válvula está pintada"], a: 0, why: "El condensado caliente, los químicos y la presión almacenada matan. Drene, purgue y verifique." },
  { id: "hc-23", category: "hazcom", topic: "HCS 2024", q: "Las actualizaciones de Comunicación de peligros de OSHA se alinearon con revisiones posteriores de GHS. El empleador debe:", choices: ["Mantener etiquetas y SDS actuales y capacitar a los empleados sobre cualquier elemento nuevo de formato de etiqueta/SDS que aplique a sus químicos", "Ignorar las actualizaciones si se capacitó en 2013", "Dejar de usar pictogramas", "Quitar la Sección 16"], a: 0, why: "Manténgase al día con las enmiendas de 1910.1200. Los distribuidores y fabricantes tienen fechas de vigencia por fases. La capacitación sigue siendo deber del empleador." },
  { id: "hc-24", category: "hazcom", topic: "Recipiente pequeño", q: "Los recipientes enviados muy pequeños pueden usar:", choices: ["Etiquetado reducido especificado en algunos casos, pero los trabajadores igual necesitan acceso a la información completa de peligros", "Ninguna información", "Solo un SKU", "Una calavera hecha a mano"], a: 0, why: "1910.1200(f) tiene disposiciones para paquetes pequeños. Las etiquetas de trabajo igual deben comunicar los peligros." },
  { id: "hc-25", category: "hazcom", topic: "Distribuidor", q: "Un distribuidor que envía químicos peligrosos debe:", choices: ["Asegurar que los recipientes estén etiquetados y que se proporcionen SDS aguas abajo", "Quitar las etiquetas para que se vea ordenado", "Enviar sin SDS si el cliente “ya sabe”", "Usar solo etiquetas en español en todos los estados"], a: 0, why: "Los fabricantes, importadores y distribuidores tienen deberes de SDS de 1910.1200(g). Los empleadores que usan químicos tienen deberes de lugar de trabajo." },
  { id: "ff-18", category: "focusFour", topic: "Estadísticas", q: "Los datos de OSHA y BLS muestran que el evento fatal principal de la construcción suele ser:", choices: ["Caídas a un nivel inferior", "Movimiento repetitivo de oficina", "Picaduras de abeja", "Cortes de papel"], a: 0, why: "El Focus Four existe porque los datos son consistentes año tras año. Controle las caídas primero." },
  { id: "ff-19", category: "focusFour", topic: "Retroceso de vehículo", q: "Los camiones de volteo y las cargadoras que retroceden en una obra son un:", choices: ["Peligro de golpes (struck-by): alarmas de retroceso, cámaras, vigías y zonas de exclusión", "Solo peligro de caída", "Solo un asunto de ruido", "Solo atrapamiento en zanja"], a: 0, why: "1926.601–602 y prácticas de zona de trabajo. Los puntos ciegos son enormes. Los vigías deben ser visibles para el conductor." },
  { id: "ff-20", category: "focusFour", topic: "Zanja más caída", q: "Una zanja sin protección que también es un peligro de pasarela puede ser:", choices: ["Tanto un peligro de derrumbe (atrapamiento) como de caída", "Ninguno", "Solo eléctrico", "Solo salud"], a: 0, why: "Los trabajadores caen a las zanjas y quedan enterrados. Resguarde o cubra, y use sistemas de protección." }
];
